/* AK-74M: the Block Bench model (data above). Parts keep the model's names, so the bolt carrier, trigger and magazine can move.
   Size: the model is scaled so its length is a real AK-74 (0.943 m). Colours are per part (no texture image is in the file). */
function buildLit(L){
 const root=new T.Group();
 const nodes=L.n.map(nd=>{const g=new T.Group();g.name=nd.n;
  if(nd.t)g.position.fromArray(nd.t);if(nd.r)g.quaternion.fromArray(nd.r);if(nd.s)g.scale.fromArray(nd.s);
  if(nd.m){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(nd.m,3));geo.setIndex(nd.ix);
   const flat=geo.toNonIndexed();flat.computeVertexNormals();g.add(new T.Mesh(flat,GM[nd.k]||GM.stl))}
  return g});
 L.n.forEach((nd,i)=>{if(nd.p>=0)nodes[nd.p].add(nodes[i])});
 const byName=n=>nodes.find(x=>x.name===n);
 const b=nodes[L.root];root.add(b);
 root.updateMatrixWorld(true);
 const len=new T.Box3().setFromObject(root);const S=0.943/(len.max.z-len.min.z);b.scale.setScalar(S);
 root.updateMatrixWorld(true);
 const box=o=>new T.Box3().setFromObject(o),cen=bx=>bx.getCenter(new T.Vector3());
 /* put the rear sight at x = 0, its top at the sight line (y = .092) and its centre at z = -.125, as the other guns */
 const rear=box(byName('RearSight')),rc=cen(rear),all=box(root);
 b.position.add(new T.Vector3(-rc.x,.092-rear.max.y,-.125-rc.z));
 root.updateMatrixWorld(true);
 const at=n=>cen(box(byName(n))),r2=box(byName('RearSight')),f2=box(byName('FrontsightMuzzel')),a2=box(root);
 const pg=at('pistolgrip'),fe=at('Forend'),mg=at('magazine');
 /* hands: the grip and the forend, with the elbows kept at the same offsets as the old AK */
 const rh=[pg.x,pg.y,pg.z],lh=[fe.x,fe.y,fe.z];
 const rE=[rh[0]+.07,rh[1]-.18,rh[2]+.45],lE=[lh[0]-.3,lh[1]-.245,lh[2]+.77];
 const h=hands(root,{rh,rE,lh,lE});
 const mag=byName('magazine');
 /* the charging handle: the right hand's offset from the grip to the bolt carrier (right side, a little forward of its centre) */
 const bcen=cen(box(byName('Boltcarrier'))),HND=[bcen.x+.035-rh[0],bcen.y-rh[1],bcen.z-rh[2]];
 const m=finish(root,b,h.arms,h.lh,mag,{lhTo:[mg.x-fe.x,mg.y-fe.y,mg.z-fe.z],sight:[0,r2.max.y,cen(r2).z],front:[0,f2.max.y,cen(f2).z],muz:[0,f2.max.y,a2.min.z]});
 m.rh=h.rh;
 /* the bolt carrier and the trigger follow the file's own keyframes, played from each shot */
 const trig=byName('Trigger');
 const keep=[L.n.findIndex(x=>x.n==='Boltcarrier'),L.n.findIndex(x=>x.n==='Trigger')];
 const chans=L.a.filter(c=>keep.includes(c.node)).map(c=>{
  const o=nodes[c.node],S3=c.path==='translation'?3:4;const t=c.times.slice(),v=c.values.slice();
  if(o===trig){const rest=v.slice(0,S3);t.push(t[t.length-1]+.06);v.push(...rest)}   /* the trigger springs back */
  return{o,path:c.path,t,v}});
 const q=new T.Quaternion(),q2=new T.Quaternion(),v3=new T.Vector3(),v4=new T.Vector3();
 function sample(c,tm){const n=c.t.length;let i=0;while(i<n-1&&c.t[i+1]<=tm)i++;const j=Math.min(i+1,n-1);
  const t0=c.t[i],t1=c.t[j],f=t1>t0?Math.min(1,Math.max(0,(tm-t0)/(t1-t0))):0;
  if(c.path==='translation'){v3.fromArray(c.v,i*3);v4.fromArray(c.v,j*3);c.o.position.copy(v3.lerp(v4,f))}
  else{q.fromArray(c.v,i*4);q2.fromArray(c.v,j*4);c.o.quaternion.copy(q.slerp(q2,f))}}
 m.cyc=1e9;m.onShot=()=>{m.cyc=0};
 /* reload, four stages (see RFR in game.js): grab the magazine; take it out, carry it to the vest, fetch a fresh one from the vest and bring it down;
    insert it into the well; rack the bolt with the right hand (reach, pull back, let go, return to the grip) while the gun levels */
 const boltN=byName('Boltcarrier'),boltRest=boltN.position.z,magRest=mag.position.clone(),DROP=.125,SC=b.scale.x;
 const ss=x=>x*x*(3-2*x),c01=x=>Math.min(1,Math.max(0,x));
 m.resetPose=()=>{boltN.position.z=boltRest;mag.rotation.set(0,0,0);mag.position.copy(magRest);m.rh.position.set(0,0,0)};
 m.reloadPose=(r,p,o)=>{let tilt=1,D=[0,0,0],Mo=[0,0,0],mv=true,mrx=0,back=0,rhD=[0,0,0];
  const lh=m.lhTo,VEST=[lh[0]-.12,lh[1]-.3,lh[2]+.05],DROPP=[lh[0],lh[1]-DROP,lh[2]];
  const L3=(a,b,k)=>[a[0]+(b[0]-a[0])*k,a[1]+(b[1]-a[1])*k,a[2]+(b[2]-a[2])*k];
  if(r===0){tilt=ss(p);D=lh.map(v=>v*ss(p))}
  else if(r===1){
   if(p<.25){D=L3(lh,DROPP,ss(p/.25));mrx=.25*ss(p/.25)}          /* the magazine comes out and drops */
   else if(p<.55){D=L3(DROPP,VEST,ss((p-.25)/.3));mrx=.25}        /* carried to the vest */
   else if(p<.68){D=VEST;mv=false}                                  /* pushed into the vest */
   else if(p<.8){D=VEST}                                            /* a fresh magazine is taken from the vest */
   else{D=L3(VEST,DROPP,ss((p-.8)/.2))}                             /* brought down, ready to insert */
   Mo=[D[0]-lh[0],D[1]-lh[1],D[2]-lh[2]]}
  else if(r===2){const f=1-ss(p),lk=1-ss(c01((p-.7)/.3));D=[lh[0]*lk,(lh[1]-DROP*f)*lk,lh[2]*lk];
   Mo=[0,-DROP*f,0];mrx=.25*f;mv=p>.1}
  else{tilt=1-ss(p);D=lh.map(v=>v*(1-ss(p)));
   const reach=ss(c01(p/.3)),pull=ss(c01((p-.3)/.2)),rel=ss(c01((p-.5)/.2)),ret=ss(c01((p-.7)/.3));
   back=.6*(pull-rel);const k=reach*(1-ret);
   rhD=[HND[0]*k,HND[1]*k,HND[2]*k+back*SC]}
  m.lh.position.set(D[0],D[1],D[2]);m.rh.position.set(rhD[0],rhD[1],rhD[2]);
  mag.visible=mv;mag.rotation.x=mrx;mag.position.set(magRest.x+Mo[0]/SC,magRest.y+Mo[1]/SC,magRest.z+Mo[2]/SC);
  boltN.position.z=boltRest+back;
  o[0]=-.03*tilt;o[1]=.09*tilt;o[2]=.07*tilt;o[3]=.38*tilt;o[4]=-.5*tilt};
 const flipC=(L.flip||[]).filter(c=>c.path==='rotation').map(c=>({o:nodes[c.node],path:c.path,t:c.times.slice(),v:c.values.slice()}));
 let flipT=0;const FLIP_DUR=L.flipDur||0;
 /* the left hand reaches for the bipod while it swings: its target is the bipod's rest position in the hand's frame */
 const bipN=byName('Bipod');let bipT=null,bipHand=false;
 const _bw=new T.Vector3();
 /* bipod flip: the body follows the clip forwards while prone and back when standing; the bipod runs the other way, so it is out when prone and put away when standing */
 m.anim=dt=>{m.cyc+=dt;const tm=Math.min(m.cyc,1);for(const c of chans)sample(c,tm);
  if(flipC.length){const goal=P.stance==='prone'?FLIP_DUR:0;flipT+=Math.sign(goal-flipT)*Math.min(Math.abs(goal-flipT),dt);for(const c of flipC)sample(c,c.o.name.startsWith('Bipod')?FLIP_DUR-flipT:flipT);
   if(bipN&&m.lh){const hw=ss(c01((flipT-.4)/.35))*(1-ss(c01((flipT-1.5)/.4)));
    if(hw>0){root.updateMatrixWorld(true);bipN.getWorldPosition(_bw);m.lh.parent.worldToLocal(_bw);m.lh.position.set(_bw.x*hw,_bw.y*hw,_bw.z*hw);bipHand=true}else if(bipHand){m.lh.position.set(0,0,0);bipHand=false}}}};
 return m}
function buildAK74M(){return buildLit(AK74M)}

