 pm(b,bg(.044,.04,.22),G.wd,0,.005,-.27);pm(b,cg(.016,.016,.5),G.stl,0,.012,-.5);pm(b,bg(.03,.05,.06),G.stl,0,.0,-.66);
 sightSet(b,sy,zr,zf,.014,.04);
